namespace sv_fb4f3018c16d4fbe9ac34392753af24a.Services;

public record Product(int Id, string Name, decimal Price, string Category, double Rating, bool InStock, string ImageUrl);
public record ProductFilter(List<string>? Categories, decimal? MinPrice, decimal? MaxPrice, bool InStockOnly);
public record PagedResult<T>(List<T> Items, int TotalCount, int Page, int PageSize);

public interface IProductService
{
    Task<PagedResult<Product>> SearchAsync(ProductFilter filter, string sortBy, int page, int pageSize);
    Task<List<string>> GetCategoriesAsync();
}

@page "/catalog"
@using sv_fb4f3018c16d4fbe9ac34392753af24a.Services
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<div class="container-fluid">
    <div class="row">
        @* ── Left sidebar: filters (≈25%) ── *@
        <div class="col-lg-3 col-md-4 mb-4">
            <div class="card">
                <div class="card-header fw-bold">Filters</div>
                <div class="card-body">
                    @* Category checkboxes *@
                    <h6>Category</h6>
                    @if (categories is not null)
                    {
                        @foreach (var cat in categories)
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="checkbox" id="@($"cat-{cat}")"
                                       checked="@selectedCategories.Contains(cat)"
                                       @onchange="e => ToggleCategory(cat, (bool)e.Value!)" />
                                <label class="form-check-label" for="@($"cat-{cat}")">@cat</label>
                            </div>
                        }
                    }

                    <hr />

                    @* Price range *@
                    <h6>Price Range</h6>
                    <div class="mb-2">
                        <label class="form-label form-label-sm">Min Price</label>
                        <input type="number" class="form-control form-control-sm" min="0" step="0.01"
                               @bind="minPrice" placeholder="0.00" />
                    </div>
                    <div class="mb-2">
                        <label class="form-label form-label-sm">Max Price</label>
                        <input type="number" class="form-control form-control-sm" min="0" step="0.01"
                               @bind="maxPrice" placeholder="No limit" />
                    </div>

                    <hr />

                    @* In-stock toggle *@
                    <div class="form-check form-switch mb-3">
                        <input class="form-check-input" type="checkbox" id="inStockOnly"
                               @bind="inStockOnly" />
                        <label class="form-check-label" for="inStockOnly">In Stock Only</label>
                    </div>

                    @* Action buttons *@
                    <div class="d-grid gap-2">
                        <button class="btn btn-primary btn-sm" @onclick="ApplyFilters" disabled="@isLoading">
                            Apply Filters
                        </button>
                        <button class="btn btn-outline-secondary btn-sm" @onclick="ClearFilters" disabled="@isLoading">
                            Clear Filters
                        </button>
                    </div>
                </div>
            </div>
        </div>

        @* ── Main content area (≈75%) ── *@
        <div class="col-lg-9 col-md-8">
            @if (errorMessage is not null)
            {
                <div class="alert alert-danger" role="alert">
                    <strong>Error:</strong> @errorMessage
                </div>
            }
            else if (isLoading)
            {
                <div class="d-flex justify-content-center align-items-center py-5">
                    <div class="spinner-border text-primary me-2" role="status"></div>
                    <span>Loading products…</span>
                </div>
            }
            else if (result is null || result.Items.Count == 0)
            {
                <div class="alert alert-info text-center py-5" role="alert">
                    <h5 class="mb-1">No products found</h5>
                    <p class="mb-0">Try adjusting your filters or clearing them.</p>
                </div>
            }
            else
            {
                @* Toolbar *@
                <div class="d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2">
                    <div class="d-flex align-items-center gap-2">
                        <label class="form-label mb-0 text-nowrap" for="sortSelect">Sort by:</label>
                        <select id="sortSelect" class="form-select form-select-sm" style="width:auto"
                                @onchange="OnSortChanged">
                            @foreach (var opt in sortOptions)
                            {
                                <option value="@opt.Value" selected="@(sortBy == opt.Value)">@opt.Label</option>
                            }
                        </select>
                    </div>
                    <span class="text-muted small">
                        Showing @rangeStart–@rangeEnd of @result.TotalCount products
                    </span>
                </div>

                @* Product grid *@
                <div class="row row-cols-1 row-cols-sm-2 row-cols-xl-3 g-3 mb-4">
                    @foreach (var product in result.Items)
                    {
                        <div class="col">
                            <ProductCard Product="product"
                                         OnProductSelected="HandleProductSelected"
                                         OnAddToCart="HandleAddToCart" />
                        </div>
                    }
                </div>

                @* Pagination *@
                <nav aria-label="Product pagination">
                    <ul class="pagination justify-content-center flex-wrap">
                        <li class="page-item @(currentPage <= 1 ? "disabled" : "")">
                            <button class="page-link" @onclick="() => GoToPage(currentPage - 1)"
                                    disabled="@(currentPage <= 1)">Previous</button>
                        </li>
                        @for (int i = 1; i <= totalPages; i++)
                        {
                            var pageNum = i;
                            <li class="page-item @(pageNum == currentPage ? "active" : "")">
                                <button class="page-link" @onclick="() => GoToPage(pageNum)">@pageNum</button>
                            </li>
                        }
                        <li class="page-item @(currentPage >= totalPages ? "disabled" : "")">
                            <button class="page-link" @onclick="() => GoToPage(currentPage + 1)"
                                    disabled="@(currentPage >= totalPages)">Next</button>
                        </li>
                    </ul>
                </nav>
            }
        </div>
    </div>
</div>

@code {
    private List<string>? categories;
    private HashSet<string> selectedCategories = new();
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;

    private string sortBy = "price_asc";
    private int currentPage = 1;
    private const int PageSize = 9;

    private PagedResult<Product>? result;
    private bool isLoading;
    private string? errorMessage;

    private int totalPages => result is null || result.TotalCount == 0
        ? 1
        : (int)Math.Ceiling((double)result.TotalCount / PageSize);

    private int rangeStart => result is null ? 0 : (result.Page - 1) * result.PageSize + 1;
    private int rangeEnd => result is null ? 0 : Math.Min(result.Page * result.PageSize, result.TotalCount);

    private static readonly (string Label, string Value)[] sortOptions =
    [
        ("Price: Low to High", "price_asc"),
        ("Price: High to Low", "price_desc"),
        ("Name: A-Z", "name_asc"),
        ("Rating: Highest", "rating_desc"),
    ];

    protected override async Task OnInitializedAsync()
    {
        await LoadCategoriesAsync();
        await SearchAsync();
    }

    private async Task LoadCategoriesAsync()
    {
        try
        {
            categories = await ProductService.GetCategoriesAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load categories: {ex.Message}";
        }
    }

    private async Task SearchAsync()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            var filter = new ProductFilter(
                Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
                MinPrice: minPrice,
                MaxPrice: maxPrice,
                InStockOnly: inStockOnly
            );
            result = await ProductService.SearchAsync(filter, sortBy, currentPage, PageSize);
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load products: {ex.Message}";
            result = null;
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            selectedCategories.Add(category);
        else
            selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        currentPage = 1;
        await SearchAsync();
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        currentPage = 1;
        await SearchAsync();
    }

    private async Task OnSortChanged(ChangeEventArgs e)
    {
        sortBy = e.Value?.ToString() ?? "price_asc";
        currentPage = 1;
        await SearchAsync();
    }

    private async Task GoToPage(int page)
    {
        if (page < 1 || page > totalPages) return;
        currentPage = page;
        await SearchAsync();
    }

    private void HandleProductSelected(Product product)
    {
        // Parent page handles navigation to detail page
    }

    private void HandleAddToCart(Product product)
    {
        // Add to cart logic would go here
    }
}

@using sv_fb4f3018c16d4fbe9ac34392753af24a.Services

<div class="card h-100 product-card" role="button" @onclick="() => OnProductSelected.InvokeAsync(Product)">
    @* Placeholder image *@
    <div class="card-img-top bg-light d-flex align-items-center justify-content-center"
         style="height:180px;" role="img" aria-label="@Product.Name">
        <span class="text-muted small text-center px-2">@Product.Name</span>
    </div>

    <div class="card-body d-flex flex-column">
        <h6 class="card-title mb-1">@Product.Name</h6>
        <p class="fw-bold text-primary mb-1">@Product.Price.ToString("C")</p>
        <div class="mb-2" title="@($"{Product.Rating:F1} out of 5")">
            @((MarkupString)GetStars(Product.Rating))
        </div>
        @if (!Product.InStock)
        {
            <span class="badge bg-danger mb-2">Out of Stock</span>
        }
        <button class="btn btn-sm btn-success mt-auto"
                disabled="@(!Product.InStock)"
                @onclick="OnAddToCartClicked"
                @onclick:stopPropagation="true">
            Add to Cart
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Product Product { get; set; } = default!;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    private async Task OnAddToCartClicked()
    {
        await OnAddToCart.InvokeAsync(Product);
    }

    private static string GetStars(double rating)
    {
        int full = (int)Math.Round(rating);
        int empty = 5 - full;
        return new string('★', full) + new string('☆', empty);
    }
}

.product-card {
    cursor: pointer;
    transition: box-shadow 0.15s ease-in-out, transform 0.15s ease-in-out;
}

.product-card:hover {
    box-shadow: 0 0.25rem 0.75rem rgba(0, 0, 0, 0.15);
    transform: translateY(-2px);
}

